using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class CrossingUVRepair{static CrossingUVRepair(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CrossingUVRepair.request"))return;File.Delete("CrossingUVRepair.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/CrossingUVRepair.txt",e.ToString());Debug.LogException(e);}}
static void Run(){var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var roads=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");Directory.CreateDirectory("FinalEnvironmentRoadBackup/BeforeCrossingUVRepair");File.Copy(scene.path,"FinalEnvironmentRoadBackup/BeforeCrossingUVRepair/Scene.unity",true);var log=new List<string>();int checkedCount=0,changed=0;var seen=new HashSet<Mesh>();foreach(var f in roads.GetComponentsInChildren<MeshFilter>().Where(f=>f.sharedMesh&&f.GetComponent<Renderer>()&&f.GetComponent<Renderer>().sharedMaterials.Any(m=>m&&(m.name=="Road Atlas"||m.name=="City PNG Markings")))){var bounds=f.GetComponent<Renderer>().bounds;if(bounds.size.y>.15f||bounds.size.x<25||bounds.size.z<25||bounds.size.x>65||bounds.size.z>65)continue;var m=f.sharedMesh;if(!seen.Add(m))continue;var data=typeof(FinalPNGCityDetails).GetMethod("Read",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{m});var all=(Vector2[][])data.GetType().GetField("uv").GetValue(data);if(all[0]==null)continue;var uv=all[0];int slice=Mathf.RoundToInt((uv.Average(p=>p.x)-16)/32);if(slice!=1)continue;checkedCount++;float lo=uv.Min(p=>p.x)-48,hi=uv.Max(p=>p.x)-48;bool target=f.name=="Line020"||f.name=="Line021";bool clipped=lo>.015f&&hi<.985f&&hi-lo>.75f;if(!clipped&&!target){log.Add("Checked "+f.name+" U="+lo+".."+hi+" no matching clipping");continue;}string path=AssetDatabase.GetAssetPath(m);if(!path.EndsWith(".asset"))throw new Exception("Imported road requires explicit UV copy: "+f.name);File.Copy(path,"FinalEnvironmentRoadBackup/BeforeCrossingUVRepair/"+Path.GetFileName(path),true);var p=m.vertices;var ids=Enumerable.Range(0,m.subMeshCount).SelectMany(m.GetTriangles).ToArray();var mapped=uv.Select(q=>new Vector2(48+Mathf.Lerp(.00001f,.99999f,Mathf.InverseLerp(lo,hi,q.x-48)),q.y)).ToArray();m.uv=mapped;EditorUtility.SetDirty(m);if(!p.SequenceEqual(m.vertices)||!ids.SequenceEqual(Enumerable.Range(0,m.subMeshCount).SelectMany(m.GetTriangles)))throw new Exception("Geometry unexpectedly changed");foreach(int c in new[]{1,2,3,4,5,6,7})if(all[c]!=null){var after=new List<Vector2>();m.GetUVs(c,after);if(!after.SequenceEqual(all[c]))throw new Exception("Unrelated UV changed "+f.name);}log.Add("FIXED "+f.name+" U="+lo+".."+hi+" -> full 0..1; V and geometry unchanged");changed++;}if(changed<2)throw new Exception("Expected both named crossings to be repaired");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);foreach(string name in new[]{"Line020","Line021"}){var f=roads.GetComponentsInChildren<MeshFilter>().Single(f=>f.name==name);var b=f.GetComponent<Renderer>().bounds;typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,b.center+Vector3.up*65,b.center,"Crossing-Fixed-"+name});}log.Insert(0,"SUCCESS checked junction meshes="+checkedCount+" repaired="+changed+". UV0 only; existing mesh assets updated in place, textures/materials/geometry/other UV channels unchanged. Scene and shared prefab references retained.");File.WriteAllLines("FinalEnvironmentRoadReview/CrossingUVRepair.txt",log);}
}
